// Regenerates src/abi.ts from the Foundry build of IAgateIndex. Run after `forge build` in contracts/.
import { join } from "node:path";

const root = join(import.meta.dir, "../../../..");
// AGATE_FORGE_OUT: a forge out folder other than contracts/out (a separate FOUNDRY_OUT)
const out_ = process.env.AGATE_FORGE_OUT ?? join(root, "contracts/out");
const artifact = join(out_, "IAgateIndex.sol/IAgateIndex.json");
const { abi } = await Bun.file(artifact).json();
const out = join(import.meta.dir, "../src/abi.ts");
const body =
  "// GENERATED by scripts/gen-abi.ts from contracts/out/IAgateIndex.sol/IAgateIndex.json. Do not edit.\n" +
  `export const agateIndexAbi = ${JSON.stringify(abi, null, 2)} as const;\n`;
await Bun.write(out, body);
console.log(`wrote ${out} (${abi.length} items)`);
